using System.Buffers.Binary;
using System.Globalization;
using System.Text;
using DotPython.Language.Text;

namespace DotPython.Runtime.Managed.Execution;

/// <summary>
/// The `unicodedata` module over the pinned UCD 16 database generated by
/// `tools/unicode_data/generate.py`: category, combining class, bidirectional class,
/// east-asian width, mirrored and decomposition queries, numeric values, name lookup,
/// and the four normalization forms. The 3.2 database (`ucd_3_2_0`) and the `UCD`
/// class are the recorded gaps.
/// </summary>
internal static class PythonUnicodeDataModule
{
    private const string ResourceName = "DotPython.UnicodeData16";
    private const string ErrorCode = "DPY4064";
    private const int SBase = 0xAC00;
    private const int LBase = 0x1100;
    private const int VBase = 0x1161;
    private const int TBase = 0x11A7;
    private const int LCount = 19;
    private const int VCount = 21;
    private const int TCount = 28;
    private const int NCount = VCount * TCount;
    private const int SCount = LCount * NCount;

    private static readonly Lazy<UnicodeTable> Table = new(UnicodeTable.Load);

    internal static void Initialize(PythonGlobalNamespace globals)
    {
        globals.SetValue("unidata_version", Text(Table.Value.Version));
        Add(globals, "name", Name);
        Add(globals, "lookup", Lookup);
        Add(globals, "category", CharacterFunction("category", TableCategory));
        Add(globals, "combining", CharacterFunction("combining", TableCombining));
        Add(globals, "bidirectional", CharacterFunction("bidirectional", TableBidi));
        Add(globals, "east_asian_width", CharacterFunction("east_asian_width", TableWidth));
        Add(globals, "mirrored", CharacterFunction("mirrored", TableMirrored));
        Add(globals, "decomposition", CharacterFunction("decomposition", Decomposition));
        Add(globals, "normalize", NormalizeFunction);
        Add(globals, "is_normalized", IsNormalized);
        Add(globals, "decimal", NumberFunction("decimal", 1));
        Add(globals, "digit", NumberFunction("digit", 2));
        Add(globals, "numeric", NumberFunction("numeric", 3));
        globals.SetValue(
            "__all__",
            new PythonListValue([
                Text("unidata_version"),
                Text("name"),
                Text("lookup"),
                Text("category"),
                Text("combining"),
                Text("bidirectional"),
                Text("east_asian_width"),
                Text("mirrored"),
                Text("decomposition"),
                Text("normalize"),
                Text("is_normalized"),
                Text("decimal"),
                Text("digit"),
                Text("numeric"),
            ])
        );
    }

    private static PythonTextValue Text(string value) => new(value);

    private static void Add(
        PythonGlobalNamespace globals,
        string name,
        Func<IReadOnlyList<PythonValue>, TextSpan, PythonValue> body
    ) => globals.SetValue(name, new PythonBuiltinFunctionValue(name, body));

    private static PythonRuntimeException Fault(
        string type,
        string message,
        TextSpan span = default
    ) => ManagedObjectProtocols.Fault(ErrorCode, message, span, type);

    private static int RequireCharacter(
        PythonValue value,
        string function,
        TextSpan span,
        bool positionalName = false
    )
    {
        var position = positionalName ? "argument 1" : "argument";
        if (value is PythonTextValue text)
        {
            var runes = text.Value.EnumerateRunes().ToList();
            if (runes.Count == 1)
            {
                return runes[0].Value;
            }
            var length = runes.Count;
            throw Fault(
                "TypeError",
                positionalName
                    ? $"{function}(): argument 1 must be a unicode character, "
                        + $"not a string of length {length}"
                    : $"{function}() argument must be a unicode character, "
                        + $"not a string of length {length}",
                span
            );
        }
        throw Fault(
            "TypeError",
            positionalName
                ? $"{function}() argument 1 must be a unicode character, "
                    + $"not {ManagedObjectProtocols.GetTypeName(value)}"
                : $"{function}() argument must be a unicode character, "
                    + $"not {ManagedObjectProtocols.GetTypeName(value)}",
            span
        );
    }

    private static Func<IReadOnlyList<PythonValue>, TextSpan, PythonValue> CharacterFunction(
        string name,
        Func<int, PythonValue> body
    ) =>
        (arguments, span) =>
        {
            if (arguments.Count != 1)
            {
                throw Fault("TypeError", $"{name}() takes exactly one argument", span);
            }
            return body(RequireCharacter(arguments[0], name, span));
        };

    private static PythonValue TableCategory(int codePoint) =>
        Text(Table.Value.CategoryOf(codePoint));

    private static PythonValue TableCombining(int codePoint) =>
        PythonWholeNumberValue.Create(Table.Value.CombiningOf(codePoint));

    private static PythonValue TableBidi(int codePoint) => Text(Table.Value.BidiOf(codePoint));

    private static PythonValue TableWidth(int codePoint) => Text(Table.Value.WidthOf(codePoint));

    private static PythonValue TableMirrored(int codePoint) =>
        PythonWholeNumberValue.Create(Table.Value.MirroredOf(codePoint) ? 1 : 0);

    private static PythonValue Decomposition(int codePoint)
    {
        if (!Table.Value.TryDecomposition(codePoint, out var tag, out var values))
        {
            return Text(string.Empty);
        }
        var builder = new StringBuilder();
        if (tag.Length != 0)
        {
            builder.Append('<').Append(tag).Append("> ");
        }
        builder.AppendJoin(
            ' ',
            values.Select(value => value.ToString("X4", CultureInfo.InvariantCulture))
        );
        return Text(builder.ToString());
    }

    private static PythonValue Name(IReadOnlyList<PythonValue> arguments, TextSpan span)
    {
        if (arguments.Count == 0)
        {
            throw Fault("TypeError", "name() takes at least 1 argument", span);
        }
        var ch = RequireCharacter(arguments[0], "name", span, positionalName: true);
        var found = PythonUnicodeNames.GetName(ch);
        if (found is not null)
        {
            return Text(found);
        }
        if (arguments.Count > 1)
        {
            return arguments[1];
        }
        throw Fault("ValueError", "no such name", span);
    }

    private static PythonValue Lookup(IReadOnlyList<PythonValue> arguments, TextSpan span)
    {
        if (arguments.Count != 1 || arguments[0] is not PythonTextValue name)
        {
            throw Fault(
                "TypeError",
                arguments.Count == 1
                    ? "lookup() argument must be str, not "
                        + ManagedObjectProtocols.GetTypeName(arguments[0])
                    : "lookup() takes exactly one argument",
                span
            );
        }
        var key = name.Value.ToUpperInvariant();
        if (Table.Value.LookupName(key) is { } value)
        {
            return Text(value);
        }
        throw new PythonRaisedException(
            new PythonExceptionValue("KeyError", $"\"undefined character name '{name.Value}'\"")
            {
                Arguments = [Text($"undefined character name '{name.Value}'")],
            }
        );
    }

    private static PythonValue NormalizeFunction(
        IReadOnlyList<PythonValue> arguments,
        TextSpan span
    )
    {
        if (arguments.Count != 2)
        {
            throw Fault("TypeError", "normalize() takes exactly two arguments", span);
        }
        var form = RequireForm(arguments[0], span);
        if (arguments[1] is not PythonTextValue text)
        {
            throw Fault(
                "TypeError",
                "normalize() argument 2 must be str, not "
                    + ManagedObjectProtocols.GetTypeName(arguments[1]),
                span
            );
        }
        return Text(
            Normalize(
                form,
                text.Value,
                compatibility: form is "NFKC" or "NFKD",
                compose: form is "NFC" or "NFKC"
            )
        );
    }

    private static PythonValue IsNormalized(IReadOnlyList<PythonValue> arguments, TextSpan span)
    {
        if (arguments.Count != 2)
        {
            throw Fault("TypeError", "is_normalized() takes exactly two arguments", span);
        }
        var form = RequireForm(arguments[0], span);
        if (arguments[1] is not PythonTextValue text)
        {
            throw Fault(
                "TypeError",
                "is_normalized() argument 2 must be str, not "
                    + ManagedObjectProtocols.GetTypeName(arguments[1]),
                span
            );
        }
        var normalized = Normalize(
            form,
            text.Value,
            compatibility: form is "NFKC" or "NFKD",
            compose: form is "NFC" or "NFKC"
        );
        return PythonTruthValue.FromBoolean(normalized == text.Value);
    }

    private static string RequireForm(PythonValue value, TextSpan span) =>
        value is PythonTextValue { Value: "NFC" or "NFD" or "NFKC" or "NFKD" } form
            ? form.Value
            : throw Fault("ValueError", "invalid normalization form", span);

    private static Func<IReadOnlyList<PythonValue>, TextSpan, PythonValue> NumberFunction(
        string name,
        byte kind
    ) =>
        (arguments, span) =>
        {
            if (arguments.Count == 0)
            {
                throw Fault("TypeError", $"{name}() takes at least 1 argument", span);
            }
            var ch = RequireCharacter(arguments[0], name, span);
            if (Table.Value.TryNumeric(ch, kind, out var numerator, out var denominator))
            {
                return kind == 3
                    ? new PythonFloatingPointValue((double)numerator / denominator)
                    : PythonWholeNumberValue.Create(numerator);
            }
            if (arguments.Count > 1)
            {
                return arguments[1];
            }
            throw Fault(
                "ValueError",
                kind switch
                {
                    1 => "not a decimal",
                    2 => "not a digit",
                    _ => "not a numeric character",
                },
                span
            );
        };

    // -----------------------------------------------------------------------------
    // Normalization
    // -----------------------------------------------------------------------------

    internal static string Normalize(string form, string text, bool compatibility, bool compose)
    {
        var decomposed = new List<int>(text.Length);
        foreach (var character in text)
        {
            Decompose(character, compatibility, decomposed, depth: 0);
        }
        Reorder(decomposed);
        return compose
            ? Compose(decomposed)
            : string.Concat(decomposed.Select(character => char.ConvertFromUtf32(character)));
    }

    private static void Decompose(int codePoint, bool compatibility, List<int> output, int depth)
    {
        if (depth > 32)
        {
            output.Add(codePoint);
            return;
        }
        if (codePoint is >= SBase and < SBase + SCount)
        {
            var index = codePoint - SBase;
            output.Add(LBase + index / NCount);
            output.Add(VBase + index % NCount / TCount);
            var trailing = index % TCount;
            if (trailing != 0)
            {
                output.Add(TBase + trailing);
            }
            return;
        }
        if (
            Table.Value.TryDecomposition(codePoint, out var tag, out var values)
            && (compatibility || tag.Length == 0)
        )
        {
            foreach (var value in values)
            {
                Decompose(value, compatibility, output, depth + 1);
            }
            return;
        }
        output.Add(codePoint);
    }

    /// <summary>Canonical ordering: combining marks sort stably by class within a series.</summary>
    private static void Reorder(List<int> values)
    {
        for (var index = 1; index < values.Count; index++)
        {
            var current = values[index];
            var currentClass = Table.Value.CombiningOf(current);
            if (currentClass == 0)
            {
                continue;
            }
            var position = index;
            while (position > 0)
            {
                var previousClass = Table.Value.CombiningOf(values[position - 1]);
                if (previousClass <= currentClass)
                {
                    break;
                }
                values[position] = values[position - 1];
                position--;
            }
            values[position] = current;
        }
    }

    private static string Compose(List<int> values)
    {
        if (values.Count == 0)
        {
            return string.Empty;
        }
        var result = new List<int>(values.Count) { values[0] };
        var starter = Table.Value.CombiningOf(values[0]) == 0 ? 0 : -1;
        var lastClass = starter == 0 ? 0 : Table.Value.CombiningOf(values[0]);
        for (var index = 1; index < values.Count; index++)
        {
            var current = values[index];
            var currentClass = Table.Value.CombiningOf(current);
            if (starter >= 0 && (lastClass < currentClass || (lastClass == 0 && currentClass == 0)))
            {
                var composed = HangulCompose(result[starter], current);
                if (composed == 0)
                {
                    Table.Value.TryCompose(result[starter], current, out composed);
                }
                if (composed != 0)
                {
                    result[starter] = composed;
                    continue;
                }
            }
            if (currentClass == 0)
            {
                starter = result.Count;
                lastClass = 0;
            }
            else
            {
                lastClass = currentClass;
            }
            result.Add(current);
        }
        return string.Concat(result.Select(value => char.ConvertFromUtf32(value)));
    }

    private static int HangulCompose(int first, int second)
    {
        if (first is >= LBase and < LBase + LCount && second is >= VBase and < VBase + VCount)
        {
            return SBase + (first - LBase) * NCount + (second - VBase) * TCount;
        }
        if (
            first is >= SBase and < SBase + SCount
            && (first - SBase) % TCount == 0
            && second is > TBase and < TBase + TCount
        )
        {
            return first + (second - TBase);
        }
        return 0;
    }

    // -----------------------------------------------------------------------------
    // Resource
    // -----------------------------------------------------------------------------

    private sealed class UnicodeTable
    {
        private readonly byte[] _data;
        private readonly string _version;
        private readonly string[] _categories;
        private readonly string[] _bidiNames;
        private readonly string[] _widthNames;
        private readonly string[] _tags;
        private readonly RangeTable _categoryRanges;
        private readonly RangeTable _combiningRanges;
        private readonly RangeTable _bidiRanges;
        private readonly RangeTable _widthRanges;
        private readonly RangeTable _mirrorRanges;
        private readonly int _categoryFallback;
        private readonly int _bidiFallback;
        private readonly int _widthFallback;
        private readonly Dictionary<int, (string Tag, int[] Values)> _decompositions = [];
        private readonly Dictionary<(int First, int Second), int> _compositions = [];
        private readonly Dictionary<
            (int CodePoint, byte Kind),
            (long Numerator, long Denominator)
        > _numeric = [];
        private readonly Dictionary<string, string> _names = new(StringComparer.Ordinal);

        internal string Version => _version;

        private UnicodeTable(byte[] data)
        {
            _data = data;
            var offset = 0;
            if (!data.AsSpan(0, 8).SequenceEqual("DPYUD16\0"u8))
            {
                throw new InvalidDataException("The Unicode data resource has an invalid header.");
            }
            offset = 8;
            _version = ReadString(ref offset);
            _categories = ReadStrings(ref offset);
            _bidiNames = ReadStrings(ref offset);
            _widthNames = ReadStrings(ref offset);
            _tags = ReadStrings(ref offset);
            _categoryRanges = ReadRanges(ref offset);
            _combiningRanges = ReadRanges(ref offset);
            _bidiRanges = ReadRanges(ref offset);
            _widthRanges = ReadRanges(ref offset);
            _mirrorRanges = ReadMirrorRanges(ref offset);
            _categoryFallback = Array.IndexOf(_categories, "Cn");
            _bidiFallback = Array.IndexOf(_bidiNames, "");
            _widthFallback = Array.IndexOf(_widthNames, "N");
            var decompositionCount = ReadInt(ref offset);
            for (var index = 0; index < decompositionCount; index++)
            {
                var codePoint = ReadInt(ref offset);
                var tag = _tags[ReadU16(ref offset)];
                var length = ReadU16(ref offset);
                var values = new int[length];
                for (var item = 0; item < length; item++)
                {
                    values[item] = ReadInt(ref offset);
                }
                _decompositions[codePoint] = (tag, values);
            }
            var compositionCount = ReadInt(ref offset);
            for (var index = 0; index < compositionCount; index++)
            {
                var first = ReadInt(ref offset);
                var second = ReadInt(ref offset);
                var composed = ReadInt(ref offset);
                _compositions[(first, second)] = composed;
            }
            var numericCount = ReadInt(ref offset);
            for (var index = 0; index < numericCount; index++)
            {
                var codePoint = ReadInt(ref offset);
                var kind = data[offset++];
                var numerator = BinaryPrimitives.ReadInt64LittleEndian(data.AsSpan(offset));
                offset += 8;
                var denominator = BinaryPrimitives.ReadInt64LittleEndian(data.AsSpan(offset));
                offset += 8;
                _numeric[(codePoint, kind)] = (numerator, denominator);
            }
            var nameCount = ReadInt(ref offset);
            var records = new (int Offset, int NameLength, int ValueLength)[nameCount];
            for (var index = 0; index < nameCount; index++)
            {
                records[index] = (ReadInt(ref offset), ReadInt(ref offset), ReadInt(ref offset));
            }
            var blobLength = ReadInt(ref offset);
            var blobStart = offset;
            foreach (var (nameOffset, nameLength, valueLength) in records)
            {
                var name = Encoding.UTF8.GetString(data, blobStart + nameOffset, nameLength);
                var value = Encoding.UTF8.GetString(
                    data,
                    blobStart + nameOffset + nameLength,
                    valueLength
                );
                _names[name] = value;
            }
        }

        internal static UnicodeTable Load()
        {
            using var stream =
                typeof(PythonUnicodeDataModule).Assembly.GetManifestResourceStream(ResourceName)
                ?? throw new InvalidDataException("The Unicode data resource is missing.");
            var data = new byte[(int)stream.Length];
            stream.ReadExactly(data);
            return new UnicodeTable(data);
        }

        private string ReadString(ref int offset)
        {
            var length = ReadU16(ref offset);
            var value = Encoding.UTF8.GetString(_data, offset, length);
            offset += length;
            return value;
        }

        private string[] ReadStrings(ref int offset)
        {
            var count = ReadInt(ref offset);
            var values = new string[count];
            for (var index = 0; index < count; index++)
            {
                if (offset >= _data.Length)
                {
                    throw new InvalidDataException($"Unicode string past the end at {offset}");
                }
                var length = _data[offset++];
                if (offset + length > _data.Length)
                {
                    throw new InvalidDataException($"Unicode string past the end at {offset}");
                }
                values[index] = Encoding.UTF8.GetString(_data, offset, length);
                offset += length;
            }
            return values;
        }

        private int ReadU16(ref int offset)
        {
            if (offset + 2 > _data.Length)
            {
                throw new InvalidDataException($"Unicode data read past the end at {offset}");
            }
            var value = BinaryPrimitives.ReadUInt16LittleEndian(_data.AsSpan(offset));
            offset += 2;
            return value;
        }

        private int ReadInt(ref int offset)
        {
            if (offset + 4 > _data.Length)
            {
                throw new InvalidDataException($"Unicode data read past the end at {offset}");
            }
            var value = BinaryPrimitives.ReadInt32LittleEndian(_data.AsSpan(offset));
            offset += 4;
            return value;
        }

        /// <summary>The mirrored section carries only the true ranges, without a value byte.</summary>
        private RangeTable ReadMirrorRanges(ref int offset)
        {
            var count = ReadInt(ref offset);
            var starts = new int[count];
            var ends = new int[count];
            var values = new int[count];
            for (var index = 0; index < count; index++)
            {
                starts[index] = ReadInt(ref offset);
                ends[index] = ReadInt(ref offset);
                values[index] = 1;
            }
            return new RangeTable(starts, ends, values);
        }

        private RangeTable ReadRanges(ref int offset)
        {
            var count = ReadInt(ref offset);
            var starts = new int[count];
            var ends = new int[count];
            var values = new int[count];
            for (var index = 0; index < count; index++)
            {
                starts[index] = ReadInt(ref offset);
                ends[index] = ReadInt(ref offset);
                values[index] = _data[offset++];
            }
            return new RangeTable(starts, ends, values);
        }

        internal string CategoryOf(int codePoint) =>
            _categories[_categoryRanges.ValueOf(codePoint, _categoryFallback)];

        internal int CombiningOf(int codePoint) => _combiningRanges.ValueOf(codePoint, 0);

        internal string BidiOf(int codePoint) =>
            _bidiNames[_bidiRanges.ValueOf(codePoint, _bidiFallback)];

        internal string WidthOf(int codePoint) =>
            _widthNames[_widthRanges.ValueOf(codePoint, _widthFallback)];

        internal bool MirroredOf(int codePoint) => _mirrorRanges.ValueOf(codePoint, 0) != 0;

        internal bool TryDecomposition(int codePoint, out string tag, out int[] values)
        {
            if (_decompositions.TryGetValue(codePoint, out var found))
            {
                tag = found.Tag;
                values = found.Values;
                return true;
            }
            tag = string.Empty;
            values = [];
            return false;
        }

        internal bool TryCompose(int first, int second, out int composed) =>
            _compositions.TryGetValue((first, second), out composed);

        internal bool TryNumeric(int codePoint, byte kind, out long numerator, out long denominator)
        {
            if (_numeric.TryGetValue((codePoint, kind), out var value))
            {
                numerator = value.Numerator;
                denominator = value.Denominator;
                return true;
            }
            numerator = 0;
            denominator = 1;
            return false;
        }

        internal string? LookupName(string name) =>
            _names.TryGetValue(name, out var value) ? value : null;

        private sealed class RangeTable(int[] starts, int[] ends, int[] values)
        {
            internal int ValueOf(int codePoint, int fallback)
            {
                var low = 0;
                var high = starts.Length - 1;
                while (low <= high)
                {
                    var middle = low + (high - low) / 2;
                    if (codePoint < starts[middle])
                    {
                        high = middle - 1;
                    }
                    else if (codePoint > ends[middle])
                    {
                        low = middle + 1;
                    }
                    else
                    {
                        return values[middle];
                    }
                }
                return fallback;
            }
        }
    }
}
